hints.text:
Un gimnasio quiere saber cuántas horas se usaron sus máquinas y cuántas están fuera de servicio.

function resumenMaquinas(maquinas) {
  let horas = 0;
  let fueraServicio = 0;
  for (let i = 0; i < maquinas.length; i++) {
    horas += maquinas[i].horasUso;
    if (maquinas[i].estado === 'rota') {
      fueraServicio++;
    }
  }
  return { horas, fueraServicio };
}

Dos variables declaradas fuera del bucle y devueltas juntas.
